// The text of the generated files (scripts/gen-histories.mjs writes it; tests/histories-baked.test.ts compares it with what is committed). Pure.
import type { Baked, Course, HistoryMeta } from './types.ts';

const HEAD = '// GENERATED by scripts/gen-histories.mjs from src/ui/histories/courses.ts, played on the vendored engine. Do not edit: change the course and run it again.\n';

export function render(all: { c: Course; b: Baked; meta: HistoryMeta }[]): Record<string, string> {
  const files: Record<string, string> = {};
  for (const { b } of all) files[`baked/${b.id}.generated.ts`] = `${HEAD}import type { Baked } from '../types.ts';\n\nexport const baked: Baked = ${JSON.stringify(b)};\n`;
  const loaders = all.map(({ c }) => `  '${c.id}': () => import('./baked/${c.id}.generated.ts').then((m) => m.baked),`).join('\n');
  files['index.generated.ts'] = `${HEAD}import type { Baked, HistoryMeta } from './types.ts';\n\n/** The model patients, in the menu's order. */\nexport const HISTORIES: readonly HistoryMeta[] = ${JSON.stringify(all.map((a) => a.meta), null, 1)};\n\n/** Each history's baked record, loaded when it is opened. */\nexport const LOAD: Record<string, () => Promise<Baked>> = {\n${loaders}\n};\n`;
  return files;
}
